441 |     /**
442 |      * @notice Performance fee that has accrued since last fee harvest.
443 |      * @return Accrued performance fee in underlying `asset` token.
444 |      * @dev Performance fee is based on a high water mark value. If vault share value has increased above the
445 |      *   HWM in a fee period, issue fee shares to the vault equal to the performance fee.
446 |      */
447 |     function accruedPerformanceFee() public view returns (uint256) {
448 |         uint256 highWaterMark_ = highWaterMark;
449 |         uint256 shareValue = convertToAssets(1e18);
450 |         uint256 performanceFee = fees.performance;
451 | 
452 |         return
453 |             performanceFee > 0 && shareValue > highWaterMark
454 |                 ? performanceFee.mulDiv(
455 |                     (shareValue - highWaterMark) * totalSupply(),
456 |                     1e36,
457 |                     Math.Rounding.Down
458 |                 )
459 |                 : 0;
460 |     }
